// Volter Editor's provider credential check (packages/editor-core/server/provider-credentials.ts:22-30 at b86dde8c):
// the entered fal key, sent as Authorization: Key, asks Platform pricing for flux/dev; a mistyped key is refused.
import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const test = (key, signal) => fetch('https://api.fal.ai/v1/models/pricing?endpoint_id=fal-ai/flux/dev', { headers: { Authorization: `Key ${key}` }, signal });
const mistyped = await test(`${process.env.FAL_KEY}x`, AbortSignal.timeout(15_000));
assert.equal(mistyped.status, 401);
const refusal = await mistyped.json();
assert.equal(refusal.error?.type, 'authorization_error', JSON.stringify(refusal));
const saved = await test(process.env.FAL_KEY, AbortSignal.timeout(15_000));
assert.equal(saved.status, 200);
const pricing = await saved.json();
assert.equal(pricing.prices?.[0]?.endpoint_id, 'fal-ai/flux/dev', JSON.stringify(pricing));
assert.equal(typeof pricing.prices[0].unit_price, 'number');
assert.ok(pricing.prices[0].unit);
assert.equal(pricing.has_more, false);
console.log(JSON.stringify({ refused: refusal.error.type, valid: true, price: pricing.prices[0] }));
